/**
 * Afflo Tracking Pixel
 *
 * Merchants embed this script on their website to attribute
 * purchases back to the affiliate who referred the customer.
 *
 * Usage (CDN):
 *   <script src="https://your-afflo-domain.com/api/pixel/script.js"
 *           data-org="YOUR_ORG_ID"
 *           data-host="https://your-afflo-domain.com"></script>
 *
 * Usage (npm):
 *   import { initAfflo } from "@afflo/track";
 *   initAfflo({ orgId: "YOUR_ORG_ID", host: "https://your-afflo-domain.com" });
 *   // then on purchase:
 *   window.Afflo.track("purchase", { revenue: 99.00, orderId: "ord_xyz", currency: "USD" });
 */

const STORAGE_KEY  = "_afflo_ref";
const COOKIE_DAYS  = 30;
const SCRIPT_ID    = "__afflo__";

interface AffloConfig {
  orgId: string;
  host:  string;   // e.g. "https://app.afflo.io"
}

interface TrackPayload {
  revenue:   number;
  orderId?:  string;
  currency?: string;
  email?:    string;         // optional: customer email for dedup
  [key: string]: unknown;
}

// ── Cookie helpers ────────────────────────────────────────────────────────────

function setCookie(name: string, value: string, days: number): void {
  const expires = new Date(Date.now() + days * 864e5).toUTCString();
  document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/; SameSite=Lax`;
}

function getCookie(name: string): string | null {
  const match = document.cookie.match(new RegExp(`(?:^|; )${name}=([^;]*)`));
  return match ? decodeURIComponent(match[1]) : null;
}

// ── Ref code persistence ──────────────────────────────────────────────────────

function saveRef(code: string): void {
  try { localStorage.setItem(STORAGE_KEY, code); } catch { /* private mode */ }
  setCookie(STORAGE_KEY, code, COOKIE_DAYS);
}

function loadRef(): string | null {
  try {
    const ls = localStorage.getItem(STORAGE_KEY);
    if (ls) return ls;
  } catch { /* ignore */ }
  return getCookie(STORAGE_KEY);
}

function clearRef(): void {
  try { localStorage.removeItem(STORAGE_KEY); } catch { /* ignore */ }
  document.cookie = `${STORAGE_KEY}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/`;
}

// ── Core init ─────────────────────────────────────────────────────────────────

function init(config: AffloConfig): void {
  // Read ?ref= or ?afflo_ref= from URL
  const params  = new URLSearchParams(window.location.search);
  const refCode = params.get("ref") || params.get("afflo_ref");

  if (refCode) {
    saveRef(refCode);
    // Notify Afflo server of the click (best-effort, non-blocking)
    navigator.sendBeacon(
      `${config.host}/api/pixel`,
      JSON.stringify({ event: "click", org_id: config.orgId, ref_code: refCode, url: location.href, referrer: document.referrer })
    );
  }

  // Expose global API
  (window as any).Afflo = {
    track(event: string, payload: TrackPayload): void {
      const refCode = loadRef();
      if (!refCode) return; // no affiliate attribution — nothing to record

      const body = JSON.stringify({
        event,
        org_id:   config.orgId,
        ref_code: refCode,
        url:      location.href,
        ...payload,
      });

      // Prefer sendBeacon (survives page navigation) then fall back to fetch
      const endpoint = `${config.host}/api/pixel`;
      const sent = navigator.sendBeacon?.(endpoint, body);
      if (!sent) {
        fetch(endpoint, {
          method:  "POST",
          headers: { "Content-Type": "application/json" },
          body,
          keepalive: true,
        }).catch(() => { /* non-critical */ });
      }

      // Clear the stored ref after a successful conversion so it's not
      // double-counted on a second purchase in the same session
      if (event === "purchase" || event === "sale") {
        clearRef();
      }
    },

    // Utility for SPAs: call when route changes to pick up new ?ref= params
    refresh(): void { init(config); },
  };
}

// ── Auto-init from script tag attributes ─────────────────────────────────────

function autoInit(): void {
  const script = (
    document.currentScript ||
    document.getElementById(SCRIPT_ID) ||
    document.querySelector("script[data-org]")
  ) as HTMLScriptElement | null;

  if (!script) return;

  const orgId = script.getAttribute("data-org");
  const host  = script.getAttribute("data-host") || "https://app.afflo.io";

  if (!orgId) {
    console.warn("[Afflo] Missing data-org attribute on script tag.");
    return;
  }

  init({ orgId, host });
}

// Run immediately if DOM is ready, otherwise wait for DOMContentLoaded
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", autoInit);
} else {
  autoInit();
}

// Named export for npm usage
export { init as initAfflo };
export type { AffloConfig, TrackPayload };
